SELECT Causale.Causale, Ricevuta.Data, Ricevuta.Pagato, Ricevuta.Stampa, Ricevuta.Selezione, [go]![Cognome] & " " & [go]![Nome] & ", " & [Comuni_1]![Comune] & " - " & [go]![DataN] AS Nominativo, Go.LuogoN, Go.DataN, Go.[davcna koda], RicGenerale.Data, Ricevuta.IdR, Ricevuta.IdRg, Ricevuta.IdP, Ricevuta.IdC, starsi.Cognome & " " & starsi.nome AS Genitore, Starsi.IdS, Starsi.Ricevuta, Causale.Ordina, Starsi.Cognome AS SCognome, Starsi.Nome AS SNome, Starsi.davcna AS SDavcna, Go.Via, Go.Citta, [go]![Via] & ", " & [Comuni]![Cap] & " - " & [Comuni]![Comune] AS Vive, Comuni.Comune
FROM (((((Causale INNER JOIN Ricevuta ON Causale.IdC = Ricevuta.IdC) INNER JOIN [Go] ON Ricevuta.IdP = Go.IdP) INNER JOIN (Starsi INNER JOIN LSP ON Starsi.IdS = LSP.IdS) ON Go.IdP = LSP.IdP) INNER JOIN RicGenerale ON Ricevuta.IdRg = RicGenerale.IdRg) INNER JOIN Comuni ON Go.IdCR = Comuni.IdC) INNER JOIN Comuni AS Comuni_1 ON Go.IdCN = Comuni_1.IdC
GROUP BY Causale.Causale, Ricevuta.Data, Ricevuta.Pagato, Ricevuta.Stampa, Ricevuta.Selezione, [go]![Cognome] & " " & [go]![Nome] & ", " & [Comuni_1]![Comune] & " - " & [go]![DataN], Go.LuogoN, Go.DataN, Go.[davcna koda], RicGenerale.Data, Ricevuta.IdR, Ricevuta.IdRg, Ricevuta.IdP, Ricevuta.IdC, starsi.Cognome & " " & starsi.nome, Starsi.IdS, Starsi.Ricevuta, Causale.Ordina, Starsi.Cognome, Starsi.Nome, Starsi.davcna, Go.Via, Go.Citta, [go]![Via] & ", " & [Comuni]![Cap] & " - " & [Comuni]![Comune], Comuni.Comune
HAVING (((Ricevuta.Selezione)=True) AND ((Starsi.Ricevuta)=True))
ORDER BY Causale.Ordina;
